#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

const int INF=1e9;
struct Edge {
    int to, cap, cost, type;
    Edge(int t=0,int c=0,int v=0,int ty=0): to(t), cap(c), cost(v), type(ty) {}
};
vector<int> adj[100000];
Edge edges[1000000];
int edgeCount;
int sink;
int C, d;

void initFlow(int sinkNode) {
    sink=sinkNode;
    for (int i=0; i<=sink; ++i) adj[i].clear();
    edgeCount=0;
}

void addEdge(int u, int v, int cap, int cost, int type) {
    adj[u].push_back(edgeCount);
    edges[edgeCount]=Edge(v,cap,cost,type);
    edgeCount++;
    adj[v].push_back(edgeCount);
    if (type==1) {
        edges[edgeCount]=Edge(u,0,-C+d,type);
        edgeCount++;
    } else {
        edges[edgeCount]=Edge(u,0,-cost,type);
        edgeCount++;
    }
}

int dist[100000], inQ[100000], queue[100000], parent[100000];

int minCostFlow() {
    for (int i=0; i<=sink; ++i) {
        dist[i]=INF;
        inQ[i]=0;
    }
    dist[sink]=0;
    int front=0, back=1;
    queue[0]=0;
    while (front<back) {
        int u=queue[front++];
        inQ[u]=0;
        for (int r:adj[u]) {
            int v=edges[r].to;
            if (edges[r].cap>0 && dist[u]+edges[r].cost<dist[v]) {
                dist[v]=dist[u]+edges[r].cost;
                parent[v]=r;
                if (!inQ[v]) {
                    inQ[v]=1;
                    queue[back++]=v;
                }
            }
        }
    }
    if (dist[sink]==INF) return -1;
    int cur=sink;
    while (cur!=0) {
        int r=parent[cur];
        if (edges[r].type==1) {
            if ((r&1)==1) {
                edges[r].cost+=2*d;
                edges[r^1].cost-=2*d;
            } else {
                edges[r].cost+=2*d;
                edges[r^1].cost-=2*d;
            }
        }
        edges[r].cap--;
        edges[r^1].cap++;
        cur=edges[r^1].to;
    }
    return dist[sink];
}

int totalFlow(int n) {
    int total=0;
    for (int i=0; i<n; ++i) total+=minCostFlow();
    return total;
}

int main() {
    int n,m,k;
    cin>>n>>m>>k>>C>>d;
    initFlow(n*100+1);
    for (int i=1; i<=k; ++i) {
        int x; cin>>x;
        addEdge(0,x,1,0,0);
    }
    for (int i=1; i<=99; ++i) {
        addEdge(1+i*n,100*n+1,INF,0,0);
    }
    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=99; ++j) {
            addEdge(i+(j-1)*n,i+j*n,INF,C,0);
        }
    }
    for (int i=1; i<=m; ++i) {
        int x,y; cin>>x>>y;
        for (int j=1; j<=99; ++j) {
            addEdge(x+(j-1)*n,y+j*n,INF,C+d,1);
            addEdge(y+(j-1)*n,x+j*n,INF,C+d,1);
        }
    }
    cout<<totalFlow(k)<<endl;
    return 0;
}
